begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(23);
insert into auth.users(id) values ('00000000-0000-4000-8000-000000009701'),('00000000-0000-4000-8000-000000009702');
insert into public.users(id) values ('00000000-0000-4000-8000-000000009701'),('00000000-0000-4000-8000-000000009702') on conflict do nothing;
select ok(not has_function_privilege('authenticated','public.commit_profile_banner_operation(uuid,uuid,text,boolean)','EXECUTE'),'clients cannot forge banner actors');
select ok(not has_function_privilege('anon','public.pending_profile_banner_retirements(uuid)','EXECUTE'),'anonymous clients cannot read cleanup queue');
select ok(has_function_privilege('service_role','public.commit_profile_banner_operation(uuid,uuid,text,boolean)','EXECUTE'),'authenticated API service owns lifecycle');
select public.update_public_user_profile('00000000-0000-4000-8000-000000009701','{"banner_url":"https://storage.example.test/storage/v1/object/public/banners/00000000-0000-4000-8000-000000009701/1234567890123.png"}');
select is(public.claim_profile_banner_upload('00000000-0000-4000-8000-000000009701','00000000-0000-4000-8000-000000009711','00000000-0000-4000-8000-000000009701/00000000-0000-4000-8000-000000009711.png','https://storage.example.test/storage/v1/object/public/banners/00000000-0000-4000-8000-000000009701/00000000-0000-4000-8000-000000009711.png')->>'state','reserved','operation captures current profile before upload');
select public.issue_profile_banner_upload('00000000-0000-4000-8000-000000009701','00000000-0000-4000-8000-000000009711');
select is(public.record_profile_banner_ticket('00000000-0000-4000-8000-000000009701','00000000-0000-4000-8000-000000009711'),true,'issued token lease records before returning token');
select is(public.commit_profile_banner_operation('00000000-0000-4000-8000-000000009701','00000000-0000-4000-8000-000000009711','https://storage.example.test')->>'state','committed','upload commits and retires previous object atomically');
select is((select banner_url from public.users where id='00000000-0000-4000-8000-000000009701'),'https://storage.example.test/storage/v1/object/public/banners/00000000-0000-4000-8000-000000009701/00000000-0000-4000-8000-000000009711.png','replacement becomes current');
select is((select count(*) from private.profile_banner_retirements where user_id='00000000-0000-4000-8000-000000009701' and public_url='https://storage.example.test/storage/v1/object/public/banners/00000000-0000-4000-8000-000000009701/1234567890123.png'),1::bigint,'exact previous owned object is durably queued');
select throws_ok($$select public.update_public_user_profile('00000000-0000-4000-8000-000000009701','{"banner_url":"https://storage.example.test/storage/v1/object/public/banners/00000000-0000-4000-8000-000000009701/1234567890123.png"}')$$,'22023',null,'retired URL cannot return through original generic profile RPC');
select throws_ok($$select public.update_public_user_profile('00000000-0000-4000-8000-000000009701','{"banner_url":"https://storage.example.test/storage/v1/object/public/banners/00000000-0000-4000-8000-000000009701/1234567890123.png?x=1"}')$$,'22023',null,'retired alias cannot resurrect object');
select throws_ok($$select public.update_public_user_profile('00000000-0000-4000-8000-000000009701','{"banner_url":"https://storage.example.test/storage/v1/object/public/banners/00000000-0000-4000-8000-000000009701/1234567890123.png#fragment"}')$$,'22023',null,'retired alias cannot resurrect object');
select throws_ok($$select public.update_public_user_profile('00000000-0000-4000-8000-000000009701','{"banner_url":"https://storage.example.test/storage/v1/object/public/banners/00000000-0000-4000-8000-000000009701/%31234567890123.png"}')$$,'22023',null,'retired alias cannot resurrect object');
select is(public.record_profile_banner_ticket('00000000-0000-4000-8000-000000009701','00000000-0000-4000-8000-000000009711'),false,'committed receipt cannot mint late tokens');
select public.complete_profile_banner_retirement('00000000-0000-4000-8000-000000009701','https://storage.example.test/storage/v1/object/public/banners/00000000-0000-4000-8000-000000009701/1234567890123.png',true);
select is((select deleted_at from private.profile_banner_retirements where user_id='00000000-0000-4000-8000-000000009701' and public_url='https://storage.example.test/storage/v1/object/public/banners/00000000-0000-4000-8000-000000009701/1234567890123.png'),null::timestamptz,'active token grace forbids early deletion acknowledgement');
select is(public.commit_profile_banner_operation('00000000-0000-4000-8000-000000009701','00000000-0000-4000-8000-000000009712','https://storage.example.test',true)->>'state','committed','removal retires replacement');
select public.update_public_user_profile_with_banner_lifecycle('00000000-0000-4000-8000-000000009701','{"banner_url":"https://foreign.example.test/banner.png"}','https://storage.example.test');
select is(public.commit_profile_banner_operation('00000000-0000-4000-8000-000000009701','00000000-0000-4000-8000-000000009712','https://storage.example.test',true)->>'state','committed','removal replay is idempotent');
select is((select banner_url from public.users where id='00000000-0000-4000-8000-000000009701'),'https://foreign.example.test/banner.png','replayed removal never clears a later edit');
select public.update_public_user_profile_with_banner_lifecycle('00000000-0000-4000-8000-000000009701','{"banner_url":null}','https://storage.example.test');
select ok(not exists(select 1 from private.profile_banner_retirements where public_url='https://foreign.example.test/banner.png'),'external objects never queued');
select public.update_public_user_profile_with_banner_lifecycle('00000000-0000-4000-8000-000000009701','{"banner_url":"https://storage.example.test/storage/v1/object/public/banners/00000000-0000-4000-8000-000000009702/1234567890123.png"}','https://storage.example.test');
select public.update_public_user_profile_with_banner_lifecycle('00000000-0000-4000-8000-000000009701','{"banner_url":null}','https://storage.example.test');
select ok(not exists(select 1 from private.profile_banner_retirements where file_path like '00000000-0000-4000-8000-000000009702/%'),'another actor objects never queued');
select public.claim_profile_banner_upload('00000000-0000-4000-8000-000000009701','00000000-0000-4000-8000-000000009713','00000000-0000-4000-8000-000000009701/00000000-0000-4000-8000-000000009713.png','https://storage.example.test/storage/v1/object/public/banners/00000000-0000-4000-8000-000000009701/00000000-0000-4000-8000-000000009713.png');
select public.issue_profile_banner_upload('00000000-0000-4000-8000-000000009701','00000000-0000-4000-8000-000000009713');
select public.update_public_user_profile_with_banner_lifecycle('00000000-0000-4000-8000-000000009701','{"banner_url":"https://foreign.example.test/new.png"}','https://storage.example.test');
select is(public.commit_profile_banner_operation('00000000-0000-4000-8000-000000009701','00000000-0000-4000-8000-000000009713','https://storage.example.test')->>'state','conflict','delayed finalize cannot overwrite intervening edit');
select is((select banner_url from public.users where id='00000000-0000-4000-8000-000000009701'),'https://foreign.example.test/new.png','concurrent edit retained');
select ok(exists(select 1 from private.profile_banner_retirements where public_url='https://storage.example.test/storage/v1/object/public/banners/00000000-0000-4000-8000-000000009701/00000000-0000-4000-8000-000000009713.png'),'stale staged upload is retired for cleanup');
select is(public.commit_profile_banner_operation('00000000-0000-4000-8000-000000009701','00000000-0000-4000-8000-000000009713','https://storage.example.test')->>'state','conflict','stale operation retry stays conflict');
select * from finish();
rollback;
